// so-context OpenCode plugin — auto-generated by `so-context setup`
//
// Two responsibilities:
//
// 1. Session lifecycle: calls watch on session start and unwatch on
//    session end, passing the OpenCode session ID to the daemon so it can
//    maintain an accurate per-session consumer list.
//
// 2. Session ID injection: rewrites every so-context MCP tool call before it
//    reaches the daemon, injecting `_so_session_id` into the tool arguments so
//    the daemon can attribute events to the correct context window (sub-agent).
//
// Event shapes (from opencode/src/session/session.ts):
//   session.created / session.deleted
//     properties.sessionID  — the session identifier
//     properties.info       — full Session.Info object
//     properties.info.directory — the session's working directory
//
//   before_tool_call (fires per MCP tool call, can rewrite input)
//     properties.sessionID  — the calling context window's session ID
//     properties.tool       — { name, input }

import type { Plugin } from "@opencode-ai/plugin";

export const SoContextPlugin: Plugin = async ({ directory: projectDir, $ }) => {
  const binary = "{BINARY}";

  return {
    event: async ({ event }) => {
      // --- Session lifecycle ---
      if (
        event.type === "session.created" ||
        event.type === "session.deleted"
      ) {
        const dir =
          (event.properties as any)?.info?.directory ?? projectDir ?? ".";
        const cmd =
          event.type === "session.created" ? "watch" : "unwatch";
        await $`${binary} ${cmd} ${dir}`
          .nothrow()
          .quiet();
        return;
      }

      // --- Session ID injection into so-context tool calls ---
      if (event.type === "before_tool_call") {
        const props = event.properties as any;
        const toolName: string = props?.tool?.name ?? "";

        // Only intercept so-context MCP tools.
        if (!toolName.startsWith("mcp__so-context__")) return;

        const sessionId: string = props?.sessionID ?? "";
        if (!sessionId) return;

        const input = props?.tool?.input ?? {};
        return {
          tool: {
            input: {
              ...input,
              _so_session_id: sessionId,
            },
          },
        };
      }
    },
  };
};
